package com.tecsup.medico.controller;import com.tecsup.medico.model.*;import com.tecsup.medico.repository.*;import jakarta.validation.Valid;import java.time.LocalTime;import java.util.List;import org.springframework.http.HttpStatus;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;
@RestController@RequestMapping("/api/horarios")public class HorarioController{private final HorarioRepository r;private final MedicoRepository mr;public HorarioController(HorarioRepository r,MedicoRepository mr){this.r=r;this.mr=mr;}@GetMapping public List<HorarioMedico>listar(){return r.findAll();}@PostMapping@ResponseStatus(HttpStatus.CREATED)public HorarioMedico crear(@Valid@RequestBody HorarioRequest d){HorarioMedico h=new HorarioMedico();h.setMedico(mr.findById(d.idMedico()).orElseThrow(()->new ResponseStatusException(HttpStatus.BAD_REQUEST,"Médico inexistente")));h.setDiaSemana(d.diaSemana());h.setHoraInicio(d.horaInicio());h.setHoraFin(d.horaFin());if(!d.horaInicio().isBefore(d.horaFin()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"La hora inicial debe ser anterior a la final");return r.save(h);}public record HorarioRequest(@jakarta.validation.constraints.NotNull Long idMedico,@jakarta.validation.constraints.NotBlank String diaSemana,@jakarta.validation.constraints.NotNull LocalTime horaInicio,@jakarta.validation.constraints.NotNull LocalTime horaFin){}
}
